[meta]
name = Harrowmere
ambient = 0.25 0.24 0.29
fog = 0.14 0.14 0.19
fog_range = 8 40
model_range = 36
sky = dusk
atlas = harrowmere
torch = 4 0.55 0.5 0.45
start = 2 31 0
default = ,
edge_top = -0.5
open_sea = true
entity_floor = auto

// Harrowmere climbs from its harbour to the cathedral on the hill under a low, darkening dusk: a walled
// town laid out on terraces half a metre apart, its houses of dressed stone and timber under weathered
// clay-tile roofs, round towers along its wall, all stone underfoot: setts in the streets, flagged kerbs
// along them, cobbles in the lanes. Each district is entered under a stone street arch. You come in by
// the cemetery's gate in the west wall, down the alley between Corvane's hut and Pell's house, to the
// Bell Square at the heart of town, with the Silent Bell on its plinth and the shrine; Brannoc's forge
// stands to the west of it by a walled garden, the market and its fountain to the south, and below them
// the harbour, the pier and the canal. From the square the north road climbs a stair to the Gaol Ward, a
// terrace a metre up, where the old gaol's barred pit (down into the Abandoned Prison) opens in the
// middle of its plaza beside an orchard; the road runs on down to the gate under the cathedral's great
// stair, and the ward's west end meets the cathedral's own flight halfway up the hill. On the terrace at
// the top, behind its parapet, the cathedral, where the Enthroned sits at the end of the nave. East of
// the square a lane climbs past Tamsin's hall to the gap in the wall, where the green trail leaves for
// the cave.

[legend]
R = wall tex=rough_stone top=7 cap=rough_stone dress=rampart
A = wall tex=cliff_rock top=6 cap=rough_stone
// The houses' thin walls: dressed stone (H), half-timbering over an ashlar ground floor (#), and the
// timbered walls of Corvane's hut (q), a storey lower than the rest.
H = wall tex=ashlar top=5.6 cap=roof thin=0.5
# = wall tex=stone_timber top=5.6 cap=roof thin=0.5
q = wall tex=timber top=4.4 cap=roof thin=0.5
// The stone stack in the elbow of Pell's L, its chimney rising from it: a full wall, so both of the
// thin runs that meet there end against it.
^ = wall tex=ashlar top=5.6 cap=roof
C = wall tex=rough_stone h=2 top=11 cap=slate
P = wall tex=flagstone top=0.8 cap=flagstone
// The parapets along the terraces' edges: the cathedral terrace's ([) and the Gaol Ward's (]).
[ = wall tex=rough_stone top=2.7 cap=flagstone
] = wall tex=rough_stone top=1.8 cap=flagstone
, = floor tex=cobble h=0
. = floor tex=cobble h=0
s = floor tex=setts h=0
- = floor tex=setts h=0
// The flagged kerbs raised along the main streets, the gardens' earth paths and the grass inside
// their fences.
/ = floor tex=flagstone h=0.15 side=flagstone
_ = floor tex=dirt h=0 side=rough_stone
G = floor tex=grass h=0 side=rough_stone
// The Gaol Ward's terrace, a metre up: its street (0), its plaza (3) and its orchard, grassed (J)
// round the earth of its gate (o); and the east lane, half a metre up (5).
0 = floor tex=setts h=1 side=rough_stone
o = floor tex=dirt h=1 side=rough_stone
J = floor tex=grass h=1 side=rough_stone
5 = floor tex=cobble h=0.5 side=rough_stone
; = floor tex=flagstone h=2 side=rough_stone
= = floor tex=flagstone h=2 side=rough_stone
4 = floor tex=flagstone h=1.5 side=rough_stone
3 = floor tex=flagstone h=1.0 side=rough_stone
2 = floor tex=flagstone h=0.5 side=rough_stone
// The stairs: each tile half a metre below the last, its fine steps drawn over it.
1 = floor tex=flagstone h=0 side=rough_stone
n = floor tex=cathedral_floor h=2 ceil=10 ceil_tex=slate side=rough_stone dark=0.3
a = floor tex=cathedral_floor h=2.4 ceil=10 ceil_tex=slate side=rough_stone dark=0.3
i = floor tex=wood_plank h=0.2 ceil=3.4 ceil_tex=wood_plank side=wood_plank
k = floor tex=flagstone h=0 ceil=3.4 ceil_tex=wood_plank side=rough_stone
// The cheek walls either side of the cathedral's great stair, each stepping down with the stair
// beside it: its top is the top of that tile's highest step, and the stair's balustrade rakes along it.
9 = wall tex=rough_stone top=2.0 cap=flagstone
8 = wall tex=rough_stone top=1.5 cap=flagstone
7 = wall tex=rough_stone top=1.0 cap=flagstone
6 = wall tex=rough_stone top=0.5 cap=flagstone
p = floor tex=wood_plank h=0.1 side=wood_plank
// The open sea off the quays and the pier is deep: whoever goes in drowns. The canal (r) running up
// from it drowns you too (`drown=canal`), though it is no part of the open sea that `deep` draws.
~ = water tex=water h=-0.8 side=rough_stone deep
r = water tex=water h=-0.8 side=rough_stone drown=canal
V = wall tex=vine_wall top=5.5 cap=canopy
w = floor tex=jungle_floor h=0 ceil=4.2 ceil_tex=canopy side=vine_wall dark=0.2
y = floor tex=jungle_floor h=0 ceil=3.8 ceil_tex=canopy side=vine_wall dark=0.4
v = floor tex=jungle_floor h=0
c = floor tex=rough_stone h=0 ceil=3.4 ceil_tex=cliff_rock side=cliff_rock dark=0.45

