[entities]
// Villagers.
M = npc id=odrin yaw=90
m = npc id=pell yaw=0
// Hollis keeps the gaol's pit, beside its grate.
g = npc id=hollis yaw=180
f = npc id=maeve yaw=90 on=p
Z = npc id=corvane yaw=0
b = npc id=brannoc
// Captain Garrick, on the corner where the Gaol Ward's stair comes down to the east lane.
h = npc id=garrick yaw=90
// The town watch at its gates: two at the north road's, one by the cemetery's, one on the porch of the
// Vesper Gate, looking down the cathedral steps, and one at the gap in the east wall where the green
// trail leaves.
Ì = npc id=aldous yaw=90
ÿ = npc id=tobin yaw=90
¥ = npc id=fenn yaw=0
đ = npc id=wynn yaw=135 on=;
§ = npc id=reyna yaw=-90
d = npc id=tamsin yaw=-90
e = npc id=ilse yaw=-90
l = npc id=wren yaw=180
E = npc id=enthroned yaw=0 on=a
// The heart of town.
B = silent_bell on=P
S = save_statue
X = lamp_post
// The cathedral: its roof, the spire over the crossing, twin towers at the west front and two
// turrets at the apse, flying buttresses, stained glass within and without (in pairs, one pair to
// each bay between the pillars and the buttresses outside them), the great door (three
// tiles wide) with the great rose in the gable over it and another rose above the throne, pillars,
// pews facing the throne, a crimson runner down the nave, candles and banners. Its floor is marble
// lozenges in bordered panels. Its roofs stay dark slate, so the hilltop stands out over the town's clay.
É = roof span=17,7 ridge=x top=9 pitch=3.5 tex=violet_slate wall=rough_stone on=C
Ê = cathedral_spire height=15 base=11 on=n
è = cathedral_tower height=15 shift=1,-1 on=C
é = cathedral_tower height=15 shift=1,1 on=C
ê = cathedral_tower height=10 width=2.2 helm=4 turret shift=0,-2 on=C
ë = cathedral_tower height=10 width=2.2 helm=4 turret shift=0,2 on=C
ï = cathedral_portal yaw=0 height=9 rose=10.6 on=n
// The runner is laid in two stretches, one to each bake chunk, so neither drops from sight.
: = nave_runner length=3 ends=head on=n
` = nave_runner length=8 ends=foot on=n
î = rose_window rise=5.6 on=a
ì = stained_window
í = flying_buttress
ð = light y=4 color=0.95,0.3,0.32 radius=6 on=n
ñ = light y=4 color=0.35,0.45,1.0 radius=6 on=n
ò = light y=4 color=1.0,0.78,0.3 radius=6 on=n
ó = light y=4 color=0.35,0.9,0.5 radius=6 on=n
// The lamps either side of the Vesper Gate, their lanterns hung in toward it: the west one's arm
// reaches east, the east one's (č) west.
Ë = lamp_post
č = lamp_post yaw=180
// The great stair up to the door from the north road: four tiles of fine steps between raking
// balustrades on the cheek walls, lanterns on the newels at its head (it casts their light), urns at
// its foot. The plainer flight down the terrace's south side: halfway down, the Gaol Ward's west end
// meets it, and at its foot the stair street runs on down to the Bell Square.
" = grand_stair run=4 rise=0.5 steps=5 width=3 on=4
// A pale light on the porch, so the great door's carving shows from the foot of the stair.
¬ = light y=5 color=0.78,0.74,0.7 radius=9 on=;
' = stair_flight run=4 rise=0.5 steps=5 width=2 offset=-1 yaw=90 on=4
// The town's other flights, each half a metre a tile: the north road's up from the gate's yard to the
// Gaol Ward (Ć) and down again into the Bell Square (ć), the ward's step down to the east lane (Ĉ),
// and the east lane's step up from the square (ĉ) and down again through the gap in the wall (Ċ).
Ć = stair_flight run=2 rise=0.5 steps=5 width=3 yaw=-90 on=2
ć = stair_flight run=2 rise=0.5 steps=5 width=3 yaw=90 on=2
Ĉ = stair_flight run=1 rise=0.5 steps=3 width=3 yaw=90 on=2
ĉ = stair_flight run=1 rise=0.5 steps=3 width=3 yaw=180 on=1
Ċ = stair_flight run=1 rise=0.5 steps=3 width=2 offset=1 yaw=0 on=1
// A stone arch over the street wherever it passes from one district into the next, set on the
// street's middle tile, its piers on the walls either side: crenellated where the north road enters
// and leaves the Gaol Ward (Č from the gate's yard, Ą down into the Bell Square), gabled elsewhere: the
// ward up onto the cathedral's flight (ą), the cemetery road into the square and the square into the
// east lane (ă), the stair street and the harbour street (Ă).
Č = street_arch yaw=90 width=3 style=crenel on=s
Ă = street_arch yaw=90 width=3 style=gable on=s
ă = street_arch yaw=0 width=3 style=gable on=s
Ą = street_arch yaw=90 width=3 style=crenel on=0
ą = street_arch yaw=0 width=3 style=gable on=0
I = pillar
Q = pew yaw=180
O = window
Y = candles
Ó = light y=6 color=0.62,0.66,0.82 radius=9
D = banner
// The houses' roofs of weathered clay tile, each on its building's north-west corner, and each house
// built its own way: Brannoc's forge under a long gable, its door between two windows;
// Corvane's low timbered hut under a single gable; Pell's house an L of two crossing gables; Wren's
// timbering jettied out over its ashlar ground floor toward the harbour, dormers in its roof; and
// Tamsin's stone hall under a hipped roof.
À = roof span=7,7 ridge=z top=5.6 pitch=4.4 eave=0.45 tex=clay_tile wall=ashlar on=H
Á = roof span=5,5 ridge=x top=4.4 pitch=2.6 eave=0.5 tex=clay_tile wall=timber on=q
Â = roof span=6,5 ridge=x top=5.6 pitch=3.8 eave=0.45 tex=clay_tile wall=ashlar on=H
Å = roof span=4,6 ridge=z top=5.6 pitch=3.6 eave=0.45 tex=clay_tile wall=ashlar on=H
Ã = roof span=7,7 ridge=x top=5.6 pitch=4.4 eave=0.45 tex=clay_tile wall=timber on=#
Ä = roof span=7,6 ridge=x top=5.6 pitch=3.6 eave=0.45 hip=true tex=clay_tile wall=ashlar on=H
Ñ = chimney height=8 on=H
Ď = chimney height=7.5 on=^
Ā = jetty len=7 rise=3 height=2.4
ā = dormer y=5.6 yaw=-90 on=#
// Round turrets corbelled out from the houses' corners under witch-hat cones of clay tile.
¡ = roof_turret shift=0.8,-0.8 roof_tex=clay_tile on=H
¤ = roof_turret shift=0.8,0.8 roof_tex=clay_tile on=H
« = roof_turret shift=-0.8,0.8 roof_tex=clay_tile on=H
// The houses' faces: shuttered windows, balconies and arched front doors. Each house's windows are
// set either side of its door, or of the middle of a wall without one, and share one look (`seed=`
// sets their paint, grille and shutters): Brannoc's (Ē), Pell's (ē), Wren's (Ĕ) and Tamsin's (ĕ);
// Corvane's hut keeps one plain window in the middle of its north and south walls (à).
à = shutters
Ē = shutters seed=8
ē = shutters seed=0
Ĕ = shutters seed=6
ĕ = shutters seed=11
â = balcony roof_tex=clay_tile
ä = door_arch yaw=0 on=i
æ = door_arch yaw=-90 on=i
¹ = door_arch yaw=0 on=k
// The realm's crest: banners on poles about the square, the pier and the north road, carved on the
// cliff over the gaol's plaza.
Þ = banner_pole
ß = crest_plaque
// The market's fountain and the benches round it, the gaol plaza's, carts and cargo up from the quay.
Ô = fountain
Õ = bench yaw=0
Ö = bench yaw=180
Ù = bench yaw=-90
Û = hand_cart
Ü = hay_wagon yaw=-90
Ý = cargo
// The founder's statue in bronze, gone green: one north of the bell, one over the market.
¦ = town_statue yaw=90
¨ = town_statue yaw=0
// The town wall's round towers, capped in violet slate: its corners, along the walls, and the two
// at the harbour's mouth.
® = wall_tower shift=-0.8,-0.8 radius=1.8 on=R
¯ = wall_tower shift=0,-0.8 radius=1.8 on=R
° = wall_tower shift=0.8,-0.8 radius=1.8 on=R
± = wall_tower shift=-0.8,0 radius=1.8 on=R
² = wall_tower shift=0.8,0 radius=1.8 on=R
³ = wall_tower shift=-0.8,0.8 radius=2.2 height=9 on=R
´ = wall_tower shift=0.8,0.8 radius=2.2 height=9 on=R
// The shops' signs, each hung from an iron bracket by its door and painted with what it sells:
// Brannoc's anvil by the forge's door, Pell's scroll, Tamsin's flask and Corvane's crossed blades.
þ = shop_sign emblem=anvil
µ = shop_sign emblem=scroll
¶ = shop_sign emblem=flask on=s
· = shop_sign emblem=blades
// Furniture and street dressing.
× = forge_hearth
û = forge_bellows
ô = quench_trough
ã = tool_rack
ú = grindstone
¸ = weapon_rack
º = armor_stand yaw=180
* = armor_stand yaw=0
ý = ingot_pile
Í = rack
Î = crate
Ï = barrel
Ð = crate
Ò = table
L = torch radius=6
$ = hearth
% = shelf
& = cupboard
+ = bed
// The tradesfolk's furnishings: Corvane's katana stands, Pell's bookcases of books and of scrolls,
// Tamsin's apothecary drawers and a chest of drawers in the other homes.
» = katana_stand yaw=0
¼ = bookcase yaw=90
½ = bookcase style=scrolls yaw=-90
¾ = drawers style=apothecary yaw=180
> = drawers yaw=0
< = drawers yaw=-90
// Wattle fences round the gardens and the Gaol Ward's orchard.
| = fence
@ = boat on=~
÷ = boat on=r
T = tree kind=olive
ø = tree kind=pine
ù = tree kind=cypress
// The gate of the Cemetery of Ashes in the west wall: the Ashen come through it into town, and it
// shuts behind them for good.
ü = cemetery_gate yaw=0 sentinels=false
// A cold grey light falling on it, so its stone shows against the dark beyond.
¿ = light y=4.5 color=0.5,0.52,0.62 radius=7
// The old gaol's pit down into the Abandoned Prison, barred over with an iron grate in the middle of
// the Gaol Ward's plaza, under the cliff.
W = exit map=abandoned_prison at=15,32,-90 label=Descend_the_grate model=gaol_grate on=3
// A lantern on the grate's winch post, so the pit shows across the plaza at dusk.
ċ = light y=2.5 color=1.0,0.74,0.42 radius=6 on=3
// The jungle trail east of the square: a hedged path winding under a canopy that closes in and
// darkens on the way to the cave mouth into the Verdant Hollow.
// (its lantern, hung from the timbers shoring the cave's mouth, lights the way in: ¢)
K = exit map=verdant_hollow at=25,33,180 label=Enter_the_cave model=cave_mouth yaw=180 on=c
ö = mushrooms on=v
x = fungus radius=4 on=c
¢ = light y=2 color=1.0,0.72,0.4 radius=4 on=c
U = torch radius=5 on=w
õ = mushrooms on=w
F = fungus radius=4 on=y
z = mushrooms on=y
// Four grates down into the Harrow Sewers, tucked away in the town's corners, each over its own
// district below: in the north road's corner beside its gate, in the west lane below the cathedral
// terrace, and at either end of the harbour lane, against the west and east walls. The sewers join up
// beneath, so each is a short way back to the others.
! = exit map=harrow_sewers at=35,2,90 label=Descend_into_the_sewers model=sewer_grate
? = exit map=harrow_sewers at=2,14,0 label=Descend_into_the_sewers model=sewer_grate
{ = exit map=harrow_sewers at=3,36,-90 label=Descend_into_the_sewers model=sewer_grate
} = exit map=harrow_sewers at=40,37,180 label=Descend_into_the_sewers model=sewer_grate
// The Vesper Gate in the north wall, at the head of the cathedral steps: pale stone, standing open on
// Vesperholm. Nobody in town remembers it shut, or why it was opened. Lamps flank it and banners line
// the porch on the way up, so it reads from the foot of the steps.
( = exit map=vesperholm at=21,120,-90 label=Pass_the_Vesper_Gate model=vesper_gate yaw=90 on=;
// A cold light beside it, so its pale stone shows at the top of the porch.
) = light y=4.5 color=0.62,0.7,0.92 radius=7 on=;
// The north road, out through the wall to the Cinderhold, under a gate built in its likeness: black
// stone and iron, fire baskets burning on it and a red haze down the road beyond.
N = exit map=cinderhold at=30,111,-90 label=Take_the_north_road model=road_gate yaw=-90 on=-
// The skyline and the harbour's life: the harbour light on its rock out in the bay, two wrecks rotting
// in it, the windmill on the cliffs over the east lane, smoking chimney stacks on the houses, market
// stalls by the fountain, washing strung across the lane by Pell's house and nets drying on the quay.
ď = lighthouse height=16 on=~
Đ = wreck yaw=30 on=~
Ė = wreck yaw=200 on=~
ė = windmill yaw=180 on=A
Ę = house_chimney on=H
ę = house_chimney height=7.6 on=#
Ě = market_stall yaw=-90
ě = washing_line span=7.5 on=/
ĝ = net_rack yaw=-90
